/// Per-call prompt-cache routing and request shape for the provider
/// stream functions (gh-2101, GOAL #2394) — the values the
/// `StreamFunction` contract has no slot for, carried in a zone. Lives
/// beside the agent loop, which re-exports it.
library;

import 'dart:async';

/// Per-call prompt-cache routing overrides, consulted by the provider
/// stream functions built with `providerStreamFunction`.
///
/// The `StreamFunction` contract has no options slot, so per-call routing
/// (pi's `sessionId`/`cacheRetention` stream options) travels in a zone:
/// [StreamCacheRouting.runWith] installs values for every provider call
/// started inside its body — including async work such as fallback-chain
/// attempts, which run in the zone they were created in. Adapters read
/// [StreamCacheRouting.current] when a call starts; a `null` field keeps
/// the call's own defaults.
///
/// Since gh-2101 the values come from the run's `CompactionCachePolicy`
/// (lib/src/compaction/cache_policy.dart): one run-scoped routing id with
/// `short` retention, never the session's id; cache-less providers ignore
/// it. Since GOAL #2394 the session-affine hand-over call installs an
/// all-null record instead (`CompactionCachePolicy.sessionAffine`): every
/// field falls through to the values the session's own main requests
/// resolve (the resolver's bound id, the factory defaults) — the same
/// cache bucket, never a literal — and `hasExplicitRouting` tells the
/// resolver's binding whether to yield.
final class StreamCacheRouting {
  StreamCacheRouting._();

  static final Object _zoneKey = Object();
  static final Object _shapeKey = Object();

  /// The routing values active in the current zone, or `null` when no
  /// override is in effect (calls then use their built-in defaults).
  static ({String? sessionId, String? cacheRetention})? get current {
    final value = Zone.current[_zoneKey];
    return value is ({String? sessionId, String? cacheRetention})
        ? value
        : null;
  }

  /// Whether the active override names a routing value — the resolver's
  /// bound session id yields only to an EXPLICIT override (gh-2101 affine
  /// ids); an all-null record (the #2394 session-affine fallthrough) is
  /// no opinion and the resolver's binding stands, exactly as for the
  /// session's main requests.
  static bool get hasExplicitRouting {
    final routing = current;
    return routing != null &&
        (routing.sessionId != null || routing.cacheRetention != null);
  }

  /// The request-shape overrides active in the current zone (GOAL #2394
  /// hand-over call), or `null` when the call rides the adapter defaults.
  static StreamCallShape? get callShape {
    final value = Zone.current[_shapeKey];
    return value is StreamCallShape ? value : null;
  }

  /// Runs [body] with [sessionId]/[cacheRetention] overriding the cache
  /// routing of provider calls started inside it. An override is explicit:
  /// code that binds default routing values (the model-roles resolver)
  /// yields to an active override instead of replacing it. The optional
  /// [shape] installs the call's request shape (tool choice, output
  /// budget, history breakpoint, pinned Copilot initiator) the catalog
  /// builders thread into the adapter options.
  static T runWith<T>(
    T Function() body, {
    String? sessionId,
    String? cacheRetention,
    StreamCallShape? shape,
  }) {
    return runZoned(
      body,
      zoneValues: {
        _zoneKey: (sessionId: sessionId, cacheRetention: cacheRetention),
        _shapeKey: ?shape,
      },
    );
  }
}

/// The request shape of one provider call that the `StreamFunction`
/// contract has no slot for (GOAL #2394): the compaction hand-over call
/// sets all four; ordinary calls carry none of them.
final class StreamCallShape {
  /// Creates the shape; every field `null` keeps the adapter default.
  const StreamCallShape({
    this.toolChoice,
    this.maxTokens,
    this.prefixLength,
    this.copilotInitiator,
  });

  /// `tool_choice` for adapters that support it (`'none'` on the
  /// hand-over call — the reply must be text, never tool calls).
  final String? toolChoice;

  /// The explicit output-token budget (`compaction.handOver.maxTokens`).
  final int? maxTokens;

  /// The number of leading messages that form the cached history prefix —
  /// the breakpoint position adapters with explicit breakpoints place the
  /// history cache_control on (S0's last message, not the instruction).
  final int? prefixLength;

  /// The pinned Copilot `x-initiator` (`agent`/`user`) — the value S0 rode.
  final String? copilotInitiator;
}

/// Cache-aware routing + usage accounting for the compaction run's LM
/// calls (gh-2101).
///
/// ## The routing policy
///
/// The digest (checkpoint/summary) and judge calls used to opt OUT of
/// prompt caching entirely: every call shipped `cacheRetention: 'none'` and
/// a fresh routing session id, so providers discarded the prefix after each
/// call and every pass of a compaction run paid the full uncached input
/// price again. [CompactionCachePolicy.affine] flips that deliberately:
///
/// - ONE stable run-scoped routing session id shared by every digest/judge
///   call of a compaction run — providers with session affinity (OpenAI
///   `prompt_cache_key`, OpenRouter `x-session-id`) route the run's calls
///   into one cache bucket, so the next pass's request prefix can be served
///   from the cache the previous pass wrote (append-style prefix reuse);
///   Anthropic-family adapters mark the request with ephemeral
///   `cache_control` breakpoints under the `short` retention.
/// - A retention value per call class ([judgeRetention]/[digestRetention],
///   both `'short'` today): ephemeral breakpoints are enough to cover one
///   compaction run's pass ladder — minutes — and never pay the 24h
///   premium; the constants are the single place to tune per class.
/// - The id is NOT the parent conversation's session id, so compaction
///   still never reads from nor writes to the session's cache-affinity
///   bucket (the invariant the legacy `callCompleteSimple` shape existed
///   for).
///
/// Cache semantics vary by provider: adapters without cache knobs (e.g. the
/// Google adapter, implicit caching only) ignore the routing override, so
/// the policy degrades to the uncached behavior there with no extra work.
/// [CompactionCachePolicy.isolated] reproduces the legacy shape verbatim
/// (retention `'none'`, a fresh id per call) as a kill switch and for
/// tests.
///
/// ## The usage accounting
///
/// [CompactionUsageAccumulator] folds the metered `Usage` of the run's LM
/// calls (the adapters surface it through an `onUsage` callback) into
/// [CompactionUsageTotals] — the call count, the token breakdown and the
/// USD cost the pass reports render (duration/cost/cache-hit visibility).
library;

import '../agent/agent_loop.dart' show StreamCallShape, StreamCacheRouting;
import '../session/uuid.dart' show uuidv7;
import '../types.dart' show Usage;

/// Which compaction LM call class a routing decision is made for.
enum CompactionCallClass {
  /// The structured engine's hide judge (one call per hide pass).
  judge,

  /// The summarizer/digest: checkpoint folds (structured) and the classic
  /// engine's summary calls.
  digest,

  /// GOAL #2394: the merged hand-over call over the S0 prefix (rides
  /// [CompactionCachePolicy.sessionAffine] — the class only names the
  /// call for the report; the affine policy routes it like a digest).
  handOver,
}

/// The routing values one compaction LM call rides.
typedef CompactionCacheRouting = ({String? sessionId, String? cacheRetention});

/// Per-call-class cache routing for one compaction run's digest/judge
/// calls. See the library docs for the design.
final class CompactionCachePolicy {
  /// The deliberate cache-retention policy per call class (gh-2101).
  ///
  /// `'short'` — ephemeral cache breakpoints / affinity keys, enough to
  /// cover one compaction run's pass ladder, never the 24h retention
  /// premium. The classes are separate constants so a class can be tuned
  /// (or flopped to `'none'`) without touching the call-construction layer.
  static const String judgeRetention = 'short';

  /// See [judgeRetention] — the digest/checkpoint summarizer class.
  static const String digestRetention = 'short';

  const CompactionCachePolicy._(this._routingFor);

  final CompactionCacheRouting Function(CompactionCallClass klass) _routingFor;

  /// The cache-affine policy (the default): one stable run-scoped routing
  /// session id shared by every call, retention per call class. [sessionId]
  /// seeds the id (tests / callers that own run identity); null mints a
  /// fresh uuidv7 — one per policy, i.e. one per compaction run.
  factory CompactionCachePolicy.affine({String? sessionId}) {
    final id = sessionId ?? uuidv7();
    return CompactionCachePolicy._(
      (klass) => (
        sessionId: id,
        cacheRetention: klass == CompactionCallClass.judge
            ? judgeRetention
            : digestRetention,
      ),
    );
  }

  /// The session-affine policy of the merged hand-over call (GOAL #2394
  /// D4): routing = the SESSION's own values through NULL fallthrough.
  /// The zone record carries `sessionId: null, cacheRetention: null`, so
  /// `_CatalogStreamFunction.call` falls through to the factory default
  /// exactly like the session's main requests — never
  /// a literal `'short'` (a resolver-bound `long` would otherwise split
  /// the bucket). The call reads the prefix the main request just
  /// warmed; adapters without cache knobs ignore it.
  factory CompactionCachePolicy.sessionAffine() {
    return CompactionCachePolicy._((_) => _fallthroughRouting());
  }

  /// The legacy kill switch: `cacheRetention: 'none'` plus a fresh routing
  /// session id PER CALL — the pre-gh-2101 shape, kept for tests and for a
  /// config-level opt-out. Never routes through the session's bucket.
  factory CompactionCachePolicy.isolated() {
    return CompactionCachePolicy._(
      (_) => (sessionId: uuidv7(), cacheRetention: 'none'),
    );
  }

  /// The routing values the call class should run under.
  CompactionCacheRouting routingFor(CompactionCallClass klass) =>
      _routingFor(klass);

  /// Installs the class's routing as the zone override the provider
  /// adapters read ([StreamCacheRouting.runWith] body helper). [shape]
  /// (GOAL #2394) rides the same zone as the call's request shape.
  T runWith<T>(
    T Function() body,
    CompactionCallClass klass, {
    StreamCallShape? shape,
  }) {
    final routing = routingFor(klass);
    return StreamCacheRouting.runWith(
      body,
      sessionId: routing.sessionId,
      cacheRetention: routing.cacheRetention,
      shape: shape,
    );
  }
}

/// The metered usage of a set of compaction LM calls — immutable totals the
/// pass records carry and the reports render.
final class CompactionUsageTotals {
  const CompactionUsageTotals({
    required this.calls,
    required this.inputTokens,
    required this.outputTokens,
    required this.cacheReadTokens,
    required this.cacheWriteTokens,
    required this.costUsd,
  });

  final int calls;
  final int inputTokens;
  final int outputTokens;
  final int cacheReadTokens;
  final int cacheWriteTokens;
  final double costUsd;

  static const zero = CompactionUsageTotals(
    calls: 0,
    inputTokens: 0,
    outputTokens: 0,
    cacheReadTokens: 0,
    cacheWriteTokens: 0,
    costUsd: 0,
  );

  /// Share of input tokens served from the prompt cache:
  /// `cacheRead / (input + cacheRead + cacheWrite)`. `null` when the call
  /// set consumed no input at all (or no usage was reported).
  double? get cacheHitRatio {
    final total = inputTokens + cacheReadTokens + cacheWriteTokens;
    if (total == 0) return null;
    return cacheReadTokens / total;
  }

  /// The growth over an earlier snapshot of the same run, clamped at zero
  /// per field (usage counters are monotonic within a run).
  CompactionUsageTotals deltaFrom(CompactionUsageTotals earlier) {
    int clamp(int now, int then) => now > then ? now - then : 0;
    return CompactionUsageTotals(
      calls: clamp(calls, earlier.calls),
      inputTokens: clamp(inputTokens, earlier.inputTokens),
      outputTokens: clamp(outputTokens, earlier.outputTokens),
      cacheReadTokens: clamp(cacheReadTokens, earlier.cacheReadTokens),
      cacheWriteTokens: clamp(cacheWriteTokens, earlier.cacheWriteTokens),
      costUsd: costUsd > earlier.costUsd ? costUsd - earlier.costUsd : 0,
    );
  }
}

/// Mutable fold of one compaction run's LM usage. The adapters write through
/// [add] (wired as their `onUsage` callback); the engines snapshot/fold
/// deltas per pass.
final class CompactionUsageAccumulator {
  int _calls = 0;
  int _inputTokens = 0;
  int _outputTokens = 0;
  int _cacheReadTokens = 0;
  int _cacheWriteTokens = 0;
  double _costUsd = 0;

  /// Folds one provider-reported response usage into the totals. Zero usage
  /// (a provider that reports nothing) contributes nothing.
  void add(Usage usage) {
    if (usage.totalTokens == 0 &&
        usage.input == 0 &&
        usage.cacheRead == 0 &&
        usage.cacheWrite == 0) {
      return;
    }
    _calls++;
    _inputTokens += usage.input;
    _outputTokens += usage.output;
    _cacheReadTokens += usage.cacheRead;
    _cacheWriteTokens += usage.cacheWrite;
    _costUsd += usage.cost.total;
  }

  /// The totals accumulated so far.
  CompactionUsageTotals snapshot() => CompactionUsageTotals(
    calls: _calls,
    inputTokens: _inputTokens,
    outputTokens: _outputTokens,
    cacheReadTokens: _cacheReadTokens,
    cacheWriteTokens: _cacheWriteTokens,
    costUsd: _costUsd,
  );
}

/// Renders a pass duration for the compaction reports (gh-2101): `0.9s`
/// under a second, `12.4s` under a minute, `2m05s` under an hour, `1h02m`
/// beyond. `null`/non-positive input renders `null` — the reports omit the
/// metric instead of printing a zero.
String? formatPassDuration(int? milliseconds) {
  if (milliseconds == null || milliseconds <= 0) return null;
  final seconds = milliseconds / 1000;
  if (seconds < 60) return '${seconds.toStringAsFixed(1)}s';
  final minutes = seconds ~/ 60;
  if (minutes < 60) {
    final rest = (seconds - minutes * 60).round();
    return '${minutes}m${rest.toString().padLeft(2, '0')}s';
  }
  final hours = minutes ~/ 60;
  final rest = minutes - hours * 60;
  return '${hours}h${rest.toString().padLeft(2, '0')}m';
}

/// The session-affine routing record: every field null, so the provider
/// catalog resolves each one the way the session's main requests do.
CompactionCacheRouting _fallthroughRouting() =>
    (sessionId: null, cacheRetention: null);

  final String _apiKey;
  final String? Function()? _sessionId;
  final String? _cacheRetention;
  final String? _dialApiVersion;
  final bool? _dialCacheMarkersSupported;
  final ChatGptCredentialsPersist? _onChatGptCredentialsRefreshed;

  /// The pre-built HTTP client a bound provider runs on (issue #1921 —
  /// the per-provider proxy). Null keeps the adapters on the shared
  /// direct client, byte-identical to the unbound behavior.
  final http.Client? _httpClient;

  /// Route table: provider kind → adapter builder (gh-1713). The four
  /// OpenAI-compatible kinds share one builder; each builder keeps CC 1 —
  /// only its family's options construction.
  static final Map<String, _CatalogStreamBuilder> _builders = {
    'openai-completions': _CatalogStreamFunction._streamOpenAi,
    'minimax': _CatalogStreamFunction._streamOpenAi,
    'zai': _CatalogStreamFunction._streamOpenAi,
    'aiin': _CatalogStreamFunction._streamOpenAi,
    'anthropic': _CatalogStreamFunction._streamAnthropic,
    'google': _CatalogStreamFunction._streamGoogle,
    'dial': _CatalogStreamFunction._streamDial,
    'copilot': _CatalogStreamFunction._streamCopilot,
    'chatgpt-codex': _CatalogStreamFunction._streamChatGptCodex,
  };

  /// The [StreamFunction] entry point.
  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    final routing = StreamCacheRouting.current;
    final effectiveSessionId = routing?.sessionId ?? _sessionId?.call();
    final effectiveRetention = routing?.cacheRetention ?? _cacheRetention;
    final builder = _builders[_kind];
    if (builder == null) {
      // Validated by providerStreamFunction; unreachable.
      throw ConfigException('Unknown provider kind: $_kind');
    }
    // GOAL #2394: the call's request shape rides the same zone as the
    // routing (an all-null override is the session-affine fallthrough —
    // both fields resolve exactly as the session's main requests do).
    return builder(
      this,
      model,
      context,
      cancelToken,
      effectiveSessionId,
      effectiveRetention,
      StreamCacheRouting.callShape,
    );
  }

  static AssistantMessageEventStream _streamOpenAi(
    _CatalogStreamFunction self,
    Model model,
    Context context,
    CancelToken? cancelToken,
    String? sessionId,
    String? cacheRetention,
    StreamCallShape? shape,
  ) => streamOpenAICompletions(
    model,
    context,
    OpenAICompletionsOptions(
      apiKey: self._apiKey,
      cancelToken: cancelToken,
      sessionId: sessionId,
      cacheRetention: cacheRetention,
      toolChoice: shape?.toolChoice,
      maxTokens: shape?.maxTokens,
    ),
    self._httpClient,
  );

  static AssistantMessageEventStream _streamAnthropic(
    _CatalogStreamFunction self,
    Model model,
    Context context,
    CancelToken? cancelToken,
    String? sessionId,
    String? cacheRetention,
    StreamCallShape? shape,
  ) => streamAnthropic(
    model,
    context,
    AnthropicOptions(
      apiKey: self._apiKey,
      cancelToken: cancelToken,
      cacheRetention: cacheRetention,
      toolChoice: shape?.toolChoice,
      maxTokens: shape?.maxTokens,
      prefixLength: shape?.prefixLength,
    ),
    self._httpClient,
  );

  static AssistantMessageEventStream _streamGoogle(
    _CatalogStreamFunction self,
    Model model,
    Context context,
    CancelToken? cancelToken,
    String? sessionId,
    String? cacheRetention,
    StreamCallShape? shape,
  ) => streamGoogle(
    model,
    context,
    GoogleOptions(
      apiKey: self._apiKey,
      cancelToken: cancelToken,
      toolChoice: shape?.toolChoice,
      maxTokens: shape?.maxTokens,
    ),
    self._httpClient,
  );

  static AssistantMessageEventStream _streamDial(
    _CatalogStreamFunction self,
    Model model,
    Context context,
    CancelToken? cancelToken,
    String? sessionId,
    String? cacheRetention,
    StreamCallShape? shape,
  ) => streamDial(
    model,
    context,
    DialOptions(
      apiKey: self._apiKey,
      apiVersion: self._dialApiVersion,
      cancelToken: cancelToken,
      sessionId: sessionId,
      cacheRetention: cacheRetention,
      cacheMarkersSupported: self._dialCacheMarkersSupported,
    ),
    self._httpClient,
  );

  static AssistantMessageEventStream _streamCopilot(
    _CatalogStreamFunction self,
    Model model,
    Context context,
    CancelToken? cancelToken,
    String? sessionId,
    String? cacheRetention,
    StreamCallShape? shape,
  ) => streamCopilot(
    model,
    context,
    CopilotOptions(
      githubToken: self._apiKey,
      cancelToken: cancelToken,
      sessionId: sessionId,
      cacheRetention: cacheRetention,
      // D10: no tool_choice on the gateway (the nudge path covers a
      // tool-call answer); the output budget and the pinned initiator ride.
      maxTokens: shape?.maxTokens,
      initiator: shape?.copilotInitiator,
    ),
    self._httpClient,
  );

  static AssistantMessageEventStream _streamChatGptCodex(
    _CatalogStreamFunction self,
    Model model,
    Context context,
    CancelToken? cancelToken,
    String? sessionId,
    String? cacheRetention,
    StreamCallShape? shape,
  ) => streamChatGptCodex(
    model,
    context,
    credentials: self._apiKey,
    onCredentialsRefreshed: self._onChatGptCredentialsRefreshed,
    cancelToken: cancelToken,
    client: self._httpClient,
  );
}

/// Ported from pi's `assertRequestAuth`: an explicit API key wins; otherwise
/// the caller must have supplied an auth header themselves.
String? _getClientApiKey(
  String provider,
  String? apiKey,
  Map<String, String?>? headers,
) {
  if (apiKey != null) {
    return apiKey;
  }
  if (hasHeader(headers, 'authorization') ||
      hasHeader(headers, 'x-api-key') ||
      hasHeader(headers, 'cf-aig-authorization')) {
    return null;
  }
  throw StateError('No API key for provider: $provider');
}

Map<String, String> _buildHeaders(
  Model model,
  Context context,
  AnthropicOptions? options,
  _ResolvedCompat compat,
  String? apiKey,
) {
  // Ported from pi's `createClient` (API-key path).
  final betaFeatures = <String>[];
  if (_shouldUseFineGrainedToolStreamingBeta(model, context, compat)) {
    betaFeatures.add(_fineGrainedToolStreamingBeta);
  }
  // Adaptive thinking models have interleaved thinking built in; since
  // adaptive thinking is not ported yet, the beta is always requested when
  // the option allows it.
  if (options?.interleavedThinking ?? true) {
    betaFeatures.add(_interleavedThinkingBeta);
  }

  final headers = mergeProviderHeaders(
    {
      'content-type': 'application/json',
      'accept': 'application/json',
      // The Anthropic SDK sends this for pi; without an SDK we send it
      // explicitly.
      'anthropic-version': '2023-06-01',
      'x-api-key': ?apiKey,
      if (betaFeatures.isNotEmpty) 'anthropic-beta': betaFeatures.join(','),
    },
    model.headers,
    options?.headers,
  );
  return headers;
}

bool _shouldUseFineGrainedToolStreamingBeta(
  Model model,
  Context context,
  _ResolvedCompat compat,
) {
  return (context.tools?.isNotEmpty ?? false) &&
      !compat.supportsEagerToolInputStreaming;
}

/// Ported from pi's `getCacheControl` (minus the `PI_CACHE_RETENTION` env
/// lookup): `short` is the default, `long` requests a 1h TTL where the model
/// supports it, `none` disables cache breakpoints entirely.
Map<String, dynamic>? _getCacheControl(
  AnthropicOptions? options,
  _ResolvedCompat compat,
) {
  final retention = options?.cacheRetention ?? 'short';
  if (retention == 'none') {
    return null;
  }
  return {
    'type': 'ephemeral',
    if (retention == 'long' && compat.supportsLongCacheRetention) 'ttl': '1h',
  };
}

Map<String, dynamic> _buildParams(
  Model model,
  Context context,
  AnthropicOptions? options,
  _ResolvedCompat compat,
) {
  final cacheControl = _getCacheControl(options, compat);
  // GOAL #2394: the history breakpoint position of a request that extends
  // a cached prefix (S0) — the param index of the prefix's last message.
  final prefixLength = options?.prefixLength;
  var historyParamIndex = -1;
  // Thinking is requested when the options enable it (pi's StreamOptions
  // then default the level to 'minimal') or when options are silent and the
  // model carries a config-declared level (roles entry / env preconfig →
