  for (var i = 0; i < messages.length; i++) {
    final paramIndex = params.length;
    final last = _convertMessageAt(
      messages,
      i,
      params,
      allowEmptySignature: allowEmptySignature,
    );
    for (var j = i; j <= last && j < messages.length; j++) {
      paramIndexOf[j] = paramIndex;
    }
    i = last;
