/// Runs the merged hand-over pass for [c]. Returns whether the run's
/// verdict stands: `true` when the pass appended (or honestly declined
/// through [StructuredCompactor.exitReason]), `false` only on a failure
/// — a failed call, an unusable reply, a failed ask check, a ladder kill.
/// [softTriggered] waives the hard trigger gate: the host measured the
/// post-run soft line (AC11) and armed this run itself.
Future<bool> _runHandOverPass(
  StructuredCompactor c, {
  required int trigger,
  required bool force,
  required bool softTriggered,
}) async {
  final handOver = c.handOver!;
  final snapshot = c.requestSnapshot!;
  final before = c._requestTokens();
  final armed = await _handOverRange(
    c,
    trigger: trigger,
    force: force,
    softTriggered: softTriggered,
  );
  if (armed == null) return !c._ladderTerminated;
  if (c._ladderTerminated) return false;
  final watch = Stopwatch()..start();
  final usageBefore = c.usage?.snapshot();
  final openAsks = _handOverOpenAsks(armed.range);
  final instruction = _handOverInstruction(
    c,
    view: armed.view,
    range: armed.range,
    openAsks: openAsks,
    contextTokens: before,
  );
  if (c._ladderTerminated) return false;
  final HandOverCallResult result;
  try {
    result = await _callHandOver(
      c,
      handOver: handOver,
      snapshot: snapshot,
      instruction: instruction,
    );
  } on TimeoutException {
    rethrow;
  }
  // #2258: the verdict may have landed while the call ran — nothing is
  // appended, refreshed or reported after it.
  if (c._ladderTerminated) return false;
  void fail(Object error) => c.hooks?.onPass(
    StructuredCompactionPass(
      kind: 'hand-over',
      pass: ++c._pass,
      tokensBefore: before,
      tokensAfter: before,
      ok: false,
      error: error,
      durationMs: watch.elapsedMilliseconds,
      usage: c._usageDelta(usageBefore),
    ),
  );
  if (!result.ok) {
    fail(
      result.failure ??
          const CompactionException('hand-over call returned no answer'),
    );
    return false;
  }
  final reply = _handOverReply(result.response!);
  final transfer = _handOverTransfer(
    c,
    reply: reply,
    snapshot: snapshot,
    openAsks: openAsks,
    fail: fail,
  );
  if (transfer.failed) return false;
  final verdict = _handOverVerdict(
    c,
    reply: reply,
    snapshot: snapshot,
    view: armed.view,
    range: armed.range,
  );
  if (!await _appendHandOverRecords(
    c,
    verdict: verdict,
    range: armed.range,
    transfer: transfer.transfer,
  )) {
    return false;
  }
  final after = await c._refreshState();
  c.hooks?.onPass(
    _handOverPassReport(
      c,
      result: result,
      verdict: verdict,
      snapshot: snapshot,
      before: before,
      after: after,
      transfer: transfer.transfer,
      summarizedCount: transfer.transfer == null
          ? 0
          : _summarizedCount(armed.range),
      durationMs: watch.elapsedMilliseconds,
      usage: c._usageDelta(usageBefore),
    ),
  );
  return true;
}

/// The mechanical `<open-user-requests>` ground truth of the fold range:
/// the same #81 extraction the standalone checkpoint prompt rides.
List<String> _handOverOpenAsks(_CkptRange range) => userRequestCandidateLines(
  [
    for (final record in range.visible)
      if (range.coveredRecordIds.contains(record.id) &&
          record is MessageRecord &&
          record.message.role == 'user')
        record.message,
  ],
  recordIds: [
    for (final record in range.visible)
      if (range.coveredRecordIds.contains(record.id) &&
          record is MessageRecord &&
          record.message.role == 'user')
        record.id,
  ],
);

/// The appended instruction (AC3/AC6): the prompt template with the
/// pressure, the fold range aliases, the tag rule, the mechanical asks,
/// the pinned-operative block and the depth-cap `<folded-checkpoint>`
/// blocks (sanitized — older persisted checkpoints re-enter a prompt
/// healed, issue #1131; pins inside them protected, gh-1409).
String _handOverInstruction(
  StructuredCompactor c, {
  required _LedgerView view,
  required _CkptRange range,
  required List<String> openAsks,
  required int contextTokens,
}) {
  final folded = [
    for (final ckpt in c._flattenForDepthCap(range))
      '<folded-checkpoint>\n'
          '${sanitizeSummary(ckpt.text, protectedLines: c.pinnedLines).text}'
          '\n</folded-checkpoint>',
  ];
  return renderHandOverInstruction(
    template: c.handOverPrompt,
    contextTokens: contextTokens,
    windowTokens: c.window,
    foldFrom: view.seqs.seqOf(range.firstRecordId) ?? 0,
    foldTo: view.seqs.seqOf(range.lastRecordId) ?? 0,
    openUserRequests: openAsks,
    pinnedOperative: c.pinnedOperativeBlock,
    foldedCheckpoints: folded.isEmpty ? null : folded.join('\n'),
  );
}

/// `RequestSnapshot` (S0) — the last MAIN request "as sent" (GOAL #2394).
///
/// The hand-over call reads the exact prefix the session just warmed:
/// system prompt, tools and the message list of the last main send, plus
/// the record index the request's `m<seq>` tags resolve against. Every
/// main send overwrites the snapshot (last wins — the degenerate-empty
/// retry streams the same context); a snapshot is INVALID once it no
/// longer describes the live context:
///
/// - the session model changed (`prepareNextTurn` switched models — the
///   prefix a different model cached is nobody's warm bucket);
/// - a compaction run succeeded (the projection changed);
/// - the host switched branches / restored a checkpoint (the projection
///   was replaced — hosts call [RequestSnapshotStore.invalidate]).
///
/// A failed compaction run leaves the snapshot valid (nothing was
/// appended). S0 is a `Context`, not wire bytes: adapters rewrite the
/// payload — byte-identity of the prefix is asserted on the payload the
/// adapter serializes (`onPayload`), for the same model and compat.
///
/// Pure Dart — no IO.
library;

import '../context.dart';
import '../model.dart';
import '../types.dart';
import 'record_tag.dart';

/// How long a snapshot's cache bucket counts as warm (the report's
/// `bucket` signal — never a mode condition): Anthropic ephemeral
/// breakpoints and OpenAI prefix caches live ~5 minutes.
const Duration requestSnapshotBucketTtl = Duration(minutes: 5);

/// Whether [a] and [b] are the same served model (provider + id + base
/// URL) — the identity a snapshot's warm bucket is keyed by.
bool sameServedModel(Model a, Model b) =>
    a.provider == b.provider && a.id == b.id && a.baseUrl == b.baseUrl;

/// The last main request as sent. Immutable; [messages] is a private copy.
final class RequestSnapshot {
  /// Creates a snapshot; [messages] is copied, [seqMap] is the epoch the
  /// request's tags were stamped from.
  RequestSnapshot({
    required this.model,
    required List<Message> messages,
    this.systemPrompt,
    List<Tool> tools = const [],
    required this.seqMap,
    required this.sentAt,
    this.routing,
  }) : messages = List.unmodifiable(messages),
       tools = List.unmodifiable(tools);

  /// The model that served the request (`config.model` at send time —
  /// `prepareNextTurn` may have switched it away from the state model).
  final Model model;

  /// The request messages exactly as sent (post-transform — `time-left:`
  /// lines, pin carriers, pairing repairs included).
  final List<Message> messages;

  /// The request's system prompt.
  final String? systemPrompt;

  /// The request's tool manifest.
  final List<Tool> tools;

  /// The tag epoch the request was stamped from: seq → record resolution
  /// for the hand-over reply's hide list happens against THIS frozen
  /// index, never a fresh ledger (aliases drift under windowed storage
  /// and hard caps; the live edge — untaged — never names an alias).
  final TranscriptSeqMap seqMap;

